@import 'c/rlySharedStyles';

:host {
    display: block;
    --rr-blue: #0176d3;
    --rr-link: #0b5cab;
    --rr-ink: #181818;
    --rr-muted: #5c5c5c;
    --rr-line: #e5e5e5;
}

/* frame (board HubCompare 2: SLDS large, 90% wide, max 1280px; the body scrolls, header and footer stay) */
.rr-modal .rr-modal-container { width: 90%; max-width: 1280px; min-width: 0; margin: 0 auto; position: relative; }
.rr-close { position: absolute; top: -40px; right: 0; }
.rr-modal-head { text-align: left; padding: 12px 16px; border-bottom: 1px solid var(--rr-line); }
.rr-title { margin: 0; font-size: 18px; font-weight: 400; color: var(--rr-ink); }
.rr-modal-head p { margin-top: 2px; }
.rr-modal-body { padding: 12px 16px; display: flex; flex-direction: column; gap: 10px; color: var(--rr-ink); min-height: 320px; min-width: 0; }
.rr-modal-foot { display: flex; align-items: center; gap: 8px; background: #f3f3f3; }
.rr-grow { flex: 1; min-width: 0; text-align: left; }
.rr-small { font-size: 12px; margin: 0; }
.rr-mono { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 12px; }

/* pills and messages */
.rr-pill { display: inline-flex; align-items: center; height: 20px; padding: 0 8px; border-radius: 10px; font-size: 11px; font-weight: 700; white-space: nowrap; flex: none; }
.rr-msg { padding: 6px 10px; border-radius: 4px; font-size: 12px; line-height: 1.45; }
.rr-msg-bad { background: #feded8; color: #8e030f; }

/* the 2-second countdown between checks: a CSS animation, no timers */
.rr-tick { position: absolute; width: 1px; height: 1px; overflow: hidden; }
.rr-tick-run { display: block; width: 1px; height: 1px; animation: rr-tick 2s linear forwards; }
@keyframes rr-tick { from { opacity: 0.99; } to { opacity: 1; } }
.rr-tick-slow { animation-duration: 5s; }

/* build 36: progress of the parts, the pipeline offer, a large file's changed lines */
.rr-prog { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font-size: 12px; }
.rr-bar { flex: 1 1 160px; min-width: 120px; height: 7px; border-radius: 4px; background: #e9e9e9; overflow: hidden; display: flex; }
.rr-bar i { display: block; height: 100%; transition: width 0.3s; }
.rr-bar-ok { background: #2e844a; }
.rr-bar-run { background: #7db4ef; }
.rr-offer { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding: 8px 10px; border-radius: 4px; background: #f2ecfc; color: #3b0f78; font-size: 12.5px; }
.rr-pill-run { background: #eef4ff; color: #0176d3; }
.rr-patch-note { padding: 6px 10px 0; }
.rr-patch { margin: 6px 0 0; max-height: 60vh; overflow: auto; font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 11.5px; line-height: 1.45; background: #fff; }
.rr-pl { display: block; padding: 0 10px; white-space: pre; }
.rr-pl-add { background: #e3f5df; }
.rr-pl-del { background: #fde7e4; }
.rr-pl-hunk { background: #eef4ff; color: #014486; }

/* layout: list 260px, the diff fills the rest */
.rr-cmp { display: grid; grid-template-columns: 260px minmax(0, 1fr); gap: 12px; align-items: start; min-width: 0; }
.rr-c-pick { display: none; }
.rr-c-list { border: 1px solid var(--rr-line); border-radius: 4px; padding: 4px; }
.rr-c-head { margin: 4px 8px 6px; font-size: 12px; font-weight: 700; color: var(--rr-muted); text-transform: uppercase; letter-spacing: 0.04em; }
.rr-c-list ul { list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 2px; }
.rr-c-item {
    width: 100%; text-align: left; font: inherit; font-size: 13px; color: var(--rr-ink); background: transparent; cursor: pointer;
    border: 0; border-left: 3px solid transparent; border-radius: 4px; padding: 7px 8px; display: flex; flex-direction: column; gap: 3px;
}
.rr-c-item:hover { background: #f3f6fa; }
.rr-c-on, .rr-c-on:hover { background: #eef4ff; border-left-color: var(--rr-blue); }
.rr-c-l1 { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.rr-c-name { flex: 1; min-width: 0; overflow-wrap: anywhere; }
.rr-c-why { margin-top: 2px; font-size: 11px; color: var(--rr-muted); line-height: 1.35; }
.rr-c-pane { min-width: 0; }

/* loading, not available, file states */
.rr-c-card { border: 1px solid var(--rr-line); border-radius: 4px; background: #fff; overflow: hidden; }
.rr-c-cardh { padding: 8px 10px; background: #fafaf9; border-bottom: 1px solid var(--rr-line); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-c-wait { display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 8px; padding: 56px 20px; text-align: center; font-size: 13px; border: 1px solid var(--rr-line); border-radius: 4px; }
.rr-c-card .rr-c-wait { border: 0; }
.rr-c-wait-sm { padding: 24px 12px; }
.rr-c-spin { position: relative; width: 32px; height: 32px; }
.rr-c-empty { display: flex; flex-direction: column; align-items: flex-start; gap: 6px; padding: 20px 16px; font-size: 13px; }
.rr-c-empty p { margin: 0; line-height: 1.45; }

/* file picker and flow versions (in the diff's subheader) */
.rr-fpick { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; padding: 6px 10px; border-bottom: 1px solid var(--rr-line); }
.rr-fp {
    font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 11.5px; padding: 2px 8px; border-radius: 10px;
    border: 1px solid #c9c9c9; background: #fff; color: var(--rr-link); cursor: pointer;
}
.rr-fp-on { background: #eef4ff; border-color: var(--rr-blue); color: #014486; font-weight: 700; }
.rr-fver { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; padding: 7px 10px; border-bottom: 1px solid var(--rr-line); font-size: 13px; background: #fff; }
.rr-vs { color: var(--rr-muted); font-weight: 700; margin: 0 4px; }
.rr-fver-note { flex-basis: 100%; font-size: 12px; color: #8c4b02; }

@media (max-width: 900px) {
    .rr-modal .rr-modal-container { width: 100%; }
    .rr-cmp { grid-template-columns: minmax(0, 1fr); }
    .rr-c-list { display: none; }
    .rr-c-pick { display: block; }
}

/* ---- long lists (build 27, same in every bundle): search toolbar, fixed columns, pinned header, scroll inside ---- */
.rr-scroll { max-height: 26rem; overflow: auto; }
.rr-ft th, .rr-ft td { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-ft .rr-line { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rr-ft td.rr-nomatch { white-space: normal; text-align: center; color: #5c5c5c; padding: 16px; }
.rr-ft mark, .rr-scroll mark { background: #fef1cd; color: inherit; padding: 0; border-radius: 2px; }
.rr-linkbtn { border: 0; background: none; padding: 0; font: inherit; color: #0b5cab; text-decoration: underline; cursor: pointer; }
.rr-linkbtn:focus-visible { outline: 2px solid #0176d3; outline-offset: 2px; }
@media (max-width: 900px) { .rr-ft { min-width: var(--rr-ft-min, 640px); } }
@media (max-width: 600px) { .rr-scroll { max-height: 60vh; } }
.rr-c-search { padding: 0 4px 6px; }
.rr-c-list .rr-scroll { max-height: 60vh; }
.rr-nomatch-p { margin: 0; padding: 12px 8px; text-align: center; font-size: 12px; color: var(--rr-muted); }
